export function PuzzleHeader({
  children,
  className = "",
  ...props
}: PuzzleHeaderProps) {
  return (
    <header
      {...props}
      className={`bg-gray-100 dark:bg-gray-800 relative p-2 sm:p-4 md:p-8 pt-24 sm:pt-24 md:pt-24 ${className}`}
    >
      <div id="puzzle-guess-section">{children}</div>
    </header>
  );
}

