        "flex items-center gap-1 w-fit no-underline rounded-xl pr-4 pl-3.5 py-2 bg-[#153A62] text-white transition-colors duration-150 hover:bg-[#205080] hover:text-yellow-200 focus:bg-[#205080] focus:text-yellow-200 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2",
