const SpacedDetails = (props: React.ComponentProps<"details">) => (
  <details className="mb-4" {...props} />
);

// This component simulates the spoiler behavior.
// If not revealed, the row's text and background are black (hiding its content),
// and on hover they become "normal" (using hover utilities).
const SpoileredRow = ({
  revealed,
  onClick,
  children,
}: {
  revealed: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) => {
  return (
    <tr
      onClick={onClick}
      className={`cursor-pointer ${
        revealed ? "" : "text-black bg-black"
      } hover:text-current hover:bg-transparent`}
    >
      {React.Children.map(children, (child) => {
        if (
          React.isValidElement<React.HTMLAttributes<HTMLTableCellElement>>(
            child,
          ) &&
          child.type === "td"
        ) {
          return React.cloneElement(child, {
            className: "py-1 px-2",
          });
        }
        return child;
      })}
    </tr>
  );
};

// Replaces: styled.table for canned responses table
const CannedResponseTable = ({ children }: { children: React.ReactNode }) => (
  <table className="border-collapse border border-black">{children}</table>
);

// Replaces: styled.table for hint table
const SolutionHintTableElem = ({ children }: { children: React.ReactNode }) => (
  <table className="border-collapse border border-black">{children}</table>
);

const SolutionHintTableRow = ({ hint }: { hint: Hint }) => {
  const [revealed, setReveal] = useState(false);
  const onClick = useCallback(() => {
    setReveal(true);
  }, []);

  return (
    <SpoileredRow revealed={revealed} onClick={onClick}>
      <td>{hint.order}</td>
      <td>{hint.description}</td>
      <td>{hint.nudge}</td>
    </SpoileredRow>
  );
};

export const SolutionHintTable = ({ hints }: { hints: Hint[] }) => {
  if (hints.length === 0) return null;
  return (
    <SpacedDetails>
      <summary>Hints</summary>
      <SolutionHintTableElem>
        <thead>
          <tr>
            <th className="border border-black py-1 px-2">Order</th>
            <th className="border border-black py-1 px-2">Description</th>
            <th className="border border-black py-1 px-2">Nudge</th>
          </tr>
        </thead>
        <tbody>
          {hints.map((hint) => (
            <SolutionHintTableRow key={hint.order} hint={hint} />
          ))}
        </tbody>
      </SolutionHintTableElem>
    </SpacedDetails>
  );
};

const SolutionCannedResponseRow = ({
  guess,
  reply,
}: {
  guess: string;
  reply: React.JSX.Element;
}) => {
  const [revealed, setRevealed] = useState(false);
  const onClick = useCallback(() => {
    setRevealed(true);
  }, []);

  return (
    <SpoileredRow revealed={revealed} onClick={onClick}>
      <td>{guess}</td>
      <td>{reply}</td>
    </SpoileredRow>
  );
};

export const SolutionCannedResponseTable = ({
  cannedResponses,
}: {
  cannedResponses: CannedResponse[];
}) => {
  if (cannedResponses.length === 0) return null;
  return (
    <SpacedDetails>
      <summary>Canned responses</summary>
      <CannedResponseTable>
        <thead>
          <tr>
            <th className="border border-black py-1 px-2">Guess</th>
            <th className="border border-black py-1 px-2">Reply</th>
          </tr>
        </thead>
        <tbody>
          {cannedResponses.map((cannedResponse) => {
            const reply = (
              <>
                {cannedResponse.reply}
                {cannedResponse.link && (
                  <a href={cannedResponse.link.href}>
                    {cannedResponse.link.display}
                  </a>
                )}
              </>
            );
            return (
              <Fragment key={cannedResponse.guess.join(",")}>
                {cannedResponse.guess.map((guess) => (
                  <SolutionCannedResponseRow
                    key={guess}
                    guess={guess}
                    reply={reply}
                  />
                ))}
              </Fragment>
            );
          })}
        </tbody>
      </CannedResponseTable>
    </SpacedDetails>
  );
};

